This looks like the fix.

```diff
diff --git a/src/nvim/option.c b/src/nvim/option.c
index 5a7a252930..c32120be58 100644
--- a/src/nvim/option.c
+++ b/src/nvim/option.c
@@ -2855,7 +2855,11 @@ const char *did_set_global_undolevels(OptInt value, OptInt old_value)
   // sync undo before 'undolevels' changes
   // use the old value, otherwise u_sync() may not work properly
   p_ul = old_value;
-  u_sync(true);
+  FOR_ALL_BUFFERS(bp) {
+    if (bp == curbuf || bp->b_p_ul == NO_LOCAL_UNDOLEVEL) {
+      u_sync_buf(bp, true);
+    }
+  }
   p_ul = value;
   return NULL;
 }
@@ -2865,7 +2869,7 @@ const char *did_set_buflocal_undolevels(buf_T *buf, OptInt value, OptInt old_val
 {
   // use the old value, otherwise u_sync() may not work properly
   buf->b_p_ul = old_value;
-  u_sync(true);
+  u_sync_buf(buf, true);
   buf->b_p_ul = value;
   return NULL;
 }
diff --git a/src/nvim/undo.c b/src/nvim/undo.c
index 3fa0efb0db..f98d7c6cd3 100644
--- a/src/nvim/undo.c
+++ b/src/nvim/undo.c
@@ -2698,24 +2698,32 @@ void undo_fmt_time(char *buf, size_t buflen, time_t tt)
   }
 }

-/// u_sync: stop adding to the current entry list
+/// u_sync: stop adding to the current entry list of "buf".
 ///
 /// @param force  if true, also sync when no_u_sync is set.
-void u_sync(bool force)
+void u_sync_buf(buf_T *buf, bool force)
 {
   // Skip it when already synced or syncing is disabled.
-  if (curbuf->b_u_synced || (!force && no_u_sync > 0)) {
+  if (buf->b_u_synced || (!force && no_u_sync > 0)) {
     return;
   }

-  if (get_undolevel(curbuf) < 0) {
-    curbuf->b_u_synced = true;  // no entries, nothing to do
+  if (get_undolevel(buf) < 0) {
+    buf->b_u_synced = true;  // no entries, nothing to do
   } else {
-    u_getbot(curbuf);  // compute ue_bot of previous u_save
-    curbuf->b_u_curhead = NULL;
+    u_getbot(buf);  // compute ue_bot of previous u_save
+    buf->b_u_curhead = NULL;
   }
 }

+/// u_sync: stop adding to the current entry list
+///
+/// @param force  if true, also sync when no_u_sync is set.
+void u_sync(bool force)
+{
+  u_sync_buf(curbuf, force);
+}
+
 /// ":undolist": List the leafs of the undo tree
 void ex_undolist(exarg_T *eap)
 {
